CREATE TABLE IF NOT EXISTS sync_guard (id INTEGER PRIMARY KEY CHECK(id=1), token TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_records (key TEXT PRIMARY KEY, value TEXT, revision INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sync_operations (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, result TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT UNIQUE, last_seen INTEGER NOT NULL, subscription TEXT);
CREATE TABLE IF NOT EXISTS notification_target (id INTEGER PRIMARY KEY CHECK(id=1), device_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS backups (id TEXT PRIMARY KEY, created_at INTEGER NOT NULL, reason TEXT NOT NULL, revision INTEGER NOT NULL, body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS backup_dates ON backups(created_at);
